def _make_sandbox_json(sandboxes):
    """Build JSON output matching openshell sandbox list --output json."""
    return json.dumps(
        [
            {
                "name": sb["name"],
                "phase": sb.get("phase", "Ready"),
                "created_at": sb.get("created_at", "2026-06-02 12:00:00"),
                "id": sb.get("id", "fake-uuid"),
                "labels": sb.get("labels", {}),
            }
            for sb in sandboxes
        ]
    )


